  <script>
    const image = {
      title: "Alpine sunrise",
      meta: "PNG image · 4.2 MB · Added today",
      description: "A saved library preview with a warm sunrise, layered mountains, and a clean confirmation flow."
    };

    function Header() {
      return `
        <header class="site-header">
          <a class="brand" href="#" aria-label="Lumina library home">
            <span class="brand-mark" aria-hidden="true">L</span>
            <span>Lumina Library</span>
          </a>
          <p class="header-note">Image management for creative teams</p>
        </header>
      `;
    }

    function ImagePreview() {
      return `
        <section class="preview-card" aria-labelledby="image-title">
          <div class="image-frame" role="img" aria-label="${image.description}">
            <span class="image-badge">Preview ready</span>
          </div>
          <div class="card-content">
            <div>
              <h2 class="image-title" id="image-title">${image.title}</h2>
              <p class="image-meta">${image.meta}</p>
            </div>
            <button class="button button-muted trigger" type="button" aria-haspopup="dialog">
              Delete image
            </button>
          </div>
        </section>
      `;
    }

    function ProductCopy() {
      return `
        <section class="copy-panel" aria-labelledby="page-title">
          <p class="eyebrow">Library preview</p>
          <h1 id="page-title">Review before you remove.</h1>
          <p class="lede">
            Confirm destructive actions with a focused dialog that keeps the image context clear.
          </p>
          <ul class="details-list" aria-label="Image details">
            <li><span class="check-icon" aria-hidden="true">✓</span> Stored in Brand Campaigns</li>
            <li><span class="check-icon" aria-hidden="true">✓</span> Used in two shared collections</li>
            <li><span class="check-icon" aria-hidden="true">✓</span> Original file remains recoverable for 30 days</li>
          </ul>
        </section>
      `;
    }

    function DeleteDialog() {
      return `
        <div class="modal-overlay" data-modal-overlay hidden>
          <section
            class="modal"
            role="dialog"
            aria-modal="true"
            aria-labelledby="dialog-title"
            aria-describedby="dialog-description"
            tabindex="-1"
          >
            <div class="modal-icon" aria-hidden="true">
              <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                <path d="M3 6h18"></path>
                <path d="M8 6V4h8v2"></path>
                <path d="M19 6l-1 14H6L5 6"></path>
                <path d="M10 11v5"></path>
                <path d="M14 11v5"></path>
              </svg>
            </div>
            <h2 id="dialog-title">Delete “${image.title}”?</h2>
            <p id="dialog-description">
              This image will be removed from your library and shared collections. You can recover it from trash for 30 days.
            </p>
            <div class="modal-actions">
              <button class="button button-secondary" type="button" data-close-modal>Cancel</button>
              <button class="button button-danger" type="button" data-confirm-delete>Delete image</button>
            </div>
          </section>
        </div>
      `;
    }

    function App() {
      return `
        <div class="app-shell">
          ${Header()}
          <main id="main-content" tabindex="-1">
            <div class="hero">
              ${ImagePreview()}
              ${ProductCopy()}
            </div>
          </main>
        </div>
        ${DeleteDialog()}
        <div class="sr-only" aria-live="polite" data-status></div>
      `;
    }

    function setupDeleteDialog() {
      const trigger = document.querySelector(".trigger");
      const overlay = document.querySelector("[data-modal-overlay]");
      const dialog = overlay.querySelector('[role="dialog"]');
      const closeButtons = overlay.querySelectorAll("[data-close-modal]");
      const confirmButton = overlay.querySelector("[data-confirm-delete]");
      const status = document.querySelector("[data-status]");
      let previouslyFocusedElement = null;

      const getFocusableElements = () => [
        ...dialog.querySelectorAll(
          'a[href], button:not([disabled]), textarea:not([disabled]), input:not([disabled]), select:not([disabled]), [tabindex]:not([tabindex="-1"])'
        )
      ];

      const openDialog = () => {
        previouslyFocusedElement = document.activeElement;
        overlay.hidden = false;
        overlay.classList.add("is-open");
        document.body.classList.add("modal-open");
        trigger.setAttribute("aria-expanded", "true");
        dialog.focus();
      };

      const closeDialog = () => {
        overlay.classList.remove("is-open");
        overlay.hidden = true;
        document.body.classList.remove("modal-open");
        trigger.setAttribute("aria-expanded", "false");

        if (previouslyFocusedElement && typeof previouslyFocusedElement.focus === "function") {
          previouslyFocusedElement.focus();
        }
      };

      const handleKeydown = (event) => {
        if (overlay.hidden) {
          return;
        }

        if (event.key === "Escape") {
          event.preventDefault();
          closeDialog();
          return;
        }

        if (event.key !== "Tab") {
          return;
        }

        const focusableElements = getFocusableElements();
        const firstElement = focusableElements[0];
        const lastElement = focusableElements[focusableElements.length - 1];

        if (!firstElement || !lastElement) {
          event.preventDefault();
          dialog.focus();
          return;
        }

        if (event.shiftKey && document.activeElement === firstElement) {
          event.preventDefault();
          lastElement.focus();
        } else if (!event.shiftKey && document.activeElement === lastElement) {
          event.preventDefault();
          firstElement.focus();
        }
      };

      trigger.setAttribute("aria-expanded", "false");
      trigger.addEventListener("click", openDialog);
      closeButtons.forEach((button) => button.addEventListener("click", closeDialog));
      overlay.addEventListener("click", (event) => {
        if (event.target === overlay) {
          closeDialog();
        }
      });
      confirmButton.addEventListener("click", () => {
        status.textContent = `${image.title} was deleted from your library.`;
        closeDialog();
      });
      document.addEventListener("keydown", handleKeydown);
    }

    document.querySelector("#root").innerHTML = App();
    setupDeleteDialog();
  </script>
